#!/usr/bin/env bash
source "$(dirname "$0")/lib.sh"; echo "R6 malformed ExternalSecret start=$(now)"
echo "-- (a) schema violation: refreshPolicy 'Sometimes'"; printf 'apiVersion: external-secrets.io/v1\nkind: ExternalSecret\nmetadata: {name: bad-schema, namespace: trellis}\nspec:\n  refreshPolicy: Sometimes\n  secretStoreRef: {name: vault, kind: SecretStore}\n  target: {name: bad-schema}\n  data:\n  - secretKey: x\n    remoteRef: {key: trellis/llm, property: TRELLIS_LLM_API_KEY}\n' | $K apply -f - 2>&1 | cut -c1-220 | sed 's/^/   /'
echo "-- (b) valid spec, template references a missing variable"; printf 'apiVersion: external-secrets.io/v1\nkind: ExternalSecret\nmetadata: {name: bad-template, namespace: trellis}\nspec:\n  refreshPolicy: Periodic\n  refreshInterval: 1m\n  secretStoreRef: {name: vault, kind: SecretStore}\n  target:\n    name: bad-template\n    template:\n      engineVersion: v2\n      data: {out: "{{ .missing }}"}\n  data:\n  - secretKey: x\n    remoteRef: {key: trellis/llm, property: TRELLIS_LLM_API_KEY}\n' | $K apply -f - >/dev/null 2>&1; sleep 8; echo "   status=$(es trellis bad-template) msg=$(esmsg trellis bad-template) secret=$(klen trellis bad-template out)"
echo "-- (c) valid spec, property missing in the backend entry"; printf 'apiVersion: external-secrets.io/v1\nkind: ExternalSecret\nmetadata: {name: bad-property, namespace: trellis}\nspec:\n  refreshPolicy: Periodic\n  refreshInterval: 1m\n  secretStoreRef: {name: vault, kind: SecretStore}\n  target: {name: bad-property}\n  data:\n  - secretKey: x\n    remoteRef: {key: trellis/llm, property: DOES_NOT_EXIST}\n' | $K apply -f - >/dev/null 2>&1; sleep 8; echo "   status=$(es trellis bad-property) msg=$(esmsg trellis bad-property) secret=$(klen trellis bad-property x)"
echo "-- events for the two (reasons only):"; $K -n trellis get events --field-selector involvedObject.kind=ExternalSecret -o jsonpath='{range .items[*]}{.involvedObject.name} {.reason}{"\n"}{end}' | grep -E 'bad-' | sort | uniq -c | sed 's/^/   /'
$K -n trellis delete externalsecret bad-template bad-property --ignore-not-found >/dev/null; echo "R6 end=$(now)"
